import icontract

@icontract.require(lambda n: n >= 0)
@icontract.ensure(lambda n, result: n == 0 and result == 0 or n > 0 and result > 0 or True)
@icontract.ensure(lambda result: result >= 0)
def fibonacci(n: int) -> int:
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b
